/*
 * Loads the compiled Packvium engine for this platform.
 *
 * Written by hand rather than generated by `napi build`: the generated loader requires a
 * path read from an environment variable and shells out to `ldd`, and a published module
 * that does either cannot be audited by reading it. Every specifier below is a literal, so
 * the complete list of what this package can load is in this file.
 *
 * Each platform tries a binary built beside this file first (a source checkout), then the
 * prebuilt package npm installed as an optional dependency.
 */

'use strict';

/** The release this loader belongs to; a binary from any other release is refused. */
const EXPECTED_VERSION = '1.8.0';

function firstLoadable(attempts) {
  const failures = [];
  for (const attempt of attempts) {
    try {
      return attempt();
    } catch (error) {
      failures.push(error);
    }
  }
  const error = new Error(
    `@packvium/native could not load a binary for ${process.platform}/${process.arch}`,
  );
  error.cause = failures;
  throw error;
}

function loadBinding() {
  const { platform, arch } = process;
  if (platform === 'darwin' && arch === 'arm64') {
    return firstLoadable([
      () => require('./packvium-native.darwin-arm64.node'),
      () => require('@packvium/native-darwin-arm64'),
    ]);
  }
  if (platform === 'darwin' && arch === 'x64') {
    return firstLoadable([
      () => require('./packvium-native.darwin-x64.node'),
      () => require('@packvium/native-darwin-x64'),
    ]);
  }
  if (platform === 'linux' && arch === 'x64') {
    return firstLoadable([
      () => require('./packvium-native.linux-x64-gnu.node'),
      () => require('@packvium/native-linux-x64-gnu'),
    ]);
  }
  if (platform === 'win32' && arch === 'x64') {
    return firstLoadable([
      () => require('./packvium-native.win32-x64-msvc.node'),
      () => require('@packvium/native-win32-x64-msvc'),
    ]);
  }
  throw new Error(`@packvium/native has no prebuilt binary for ${platform}/${arch}`);
}

const binding = loadBinding();
const builtFor = binding.version();
if (builtFor !== EXPECTED_VERSION) {
  throw new Error(
    `@packvium/native ${EXPECTED_VERSION} loaded a binary built for ${builtFor}; reinstall it`,
  );
}

module.exports = binding;
